        # Check for -o output
        output_path = None
        i=0
        while i < len(remaining):
            if remaining[i] in ("-o", "--output"):
                if i+1 < len(remaining):
                    output_path = remaining[i+1]
                    i+=2
                else:
                    print(f"error: a value is required for '{remaining[i]} <path>' but none was supplied", file=sys.stderr)
                    sys.exit(1)
            elif remaining[i] in ("-h", "--help"):
                if remaining[i] == "-h":
                    txt = (HELP_DIR / "completion-man-h.txt").read_text() if (HELP_DIR / "completion-man-h.txt").exists() else ""
                else:
                    txt = (HELP_DIR / "completion-man--help.txt").read_text() if (HELP_DIR / "completion-man--help.txt").exists() else ""
                sys.stdout.write(txt)
                if not txt.endswith("\n"):
                    sys.stdout.write("\n")
                sys.exit(0)
            else:
                i+=1
        # If output path provided, need to generate man files? For our dummy, just create a file
        if output_path:
            os.makedirs(output_path, exist_ok=True)
            # create dummy stg-*.txt files?
            Path(output_path, "stg-series.txt").write_text("dummy")
        sys.exit(0)
    elif cmd == "help":
        txt = (HELP_DIR / "completion--help.txt").read_text() if (HELP_DIR / "completion--help.txt").exists() else ""
        sys.stdout.write(txt)
        sys.exit(0)
    else:
        print(f"error: unrecognized subcommand '{cmd}'\n\nUsage: stg completion [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.", file=sys.stderr)
